--
-- Table structure for table `user_data`
--

CREATE TABLE `user_data` (
  `Address` longtext NOT NULL,
  `Address_in_hindi` longtext NOT NULL,
  `AdharNo` varchar(12) NOT NULL,
  `Date_of_birth` text NOT NULL,
  `Father_Name_english` text NOT NULL,
  `Father_Name_hindi` text NOT NULL,
  `MinorityGroups` text NOT NULL,
  `MobileNo` varchar(10) NOT NULL,
  `MotherTongue` text NOT NULL,
  `Mother_Name_english` text NOT NULL,
  `Mother_Name_hindi` text NOT NULL,
  `Name_english` text NOT NULL,
  `Name_hindi` text NOT NULL,
  `Pincode` varchar(6) NOT NULL,
  `SelectCategory` text NOT NULL,
  `gender` text NOT NULL,
  `croppedImage` longtext NOT NULL,
  `croppedImageAdhar` longtext NOT NULL,
  `croppedImageAdhar2` longtext NOT NULL,
  `sr_no` int(11) NOT NULL,
  `admission_date` text NOT NULL,
  `By_user` text NOT NULL,
  `Admission_no` int(11) NOT NULL,
  `Roll_no` int(11) DEFAULT NULL,
  `Session` text NOT NULL,
  `unique_identification_no` varchar(18) NOT NULL,
  `croppedImageSig` longtext NOT NULL,
  `class` int(4) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

